function adrNormAnoSkill(v) {
  const matches=[...String(v||'').matchAll(/(\d+)\s*[ºo]?\s*ano/gi)].map(m=>m[1]);
  return matches.length ? `${Number(matches[matches.length-1])}º ano` : String(v||'').trim();
}
function adrNormCompSkill(v) {
  const s=norm(String(v||'')).toUpperCase();
  if(s.includes('MT') || s.includes('MAT')) return 'MT';
  if(s.includes('LP') || s.includes('PORT')) return 'LP';
  return String(v||'').trim().toUpperCase();
}
function adrNormAdrSkill(v) {
  const txt=String(v||'');
  const m = txt.match(/ADR\s*(\d+)/i) || txt.match(/(\d+)\s*[ºo]?\s*BI/i) || txt.match(/(\d+)\s*[ºo]?\s*bimestre/i);
  return m ? `ADR ${Number(m[1])}` : txt.trim();
}
function adrSkillInfo(codigo, ano, componente, adr) {
  const normalizeSkillKey = v => String(v||'').toUpperCase().replace(/[^A-Z0-9]/g,'');
  const h = normalizeSkillKey(codigo);
  const adrKey = adrNormAdrSkill(adr);
  const anoKey = adrNormAnoSkill(ano);
  const compKey = adrNormCompSkill(componente);
  const exactSet = ADR_SKILL_DESCRIPTIONS?.[adrKey]?.[anoKey]?.[compKey] || null;
  if(exactSet){
    if(exactSet[h]) return exactSet[h];
    for(const [key,info] of Object.entries(exactSet)){
      if(normalizeSkillKey(info?.codigo)===h || normalizeSkillKey(key)===h) return info;
    }
  }
  // Fallback seguro: algumas bases importadas trazem o código curricular
  // (ex.: R4pLPle15) no lugar do código Hxx. Procuramos primeiro no mesmo
  // ano/componente e depois na matriz completa, sempre preservando o texto oficial.
  const sameYearComp = ADR_SKILL_DESCRIPTIONS?.[adrKey]?.[anoKey]?.[compKey] || ADR_SKILL_DESCRIPTIONS?.[adrKey]?.[anoKey];
  const scanSets = [];
  if(sameYearComp){
    if(compKey && sameYearComp[compKey]) scanSets.push(sameYearComp[compKey]);
    else if(typeof sameYearComp==='object') Object.values(sameYearComp).forEach(v=>scanSets.push(v));
  }
  Object.values(ADR_SKILL_DESCRIPTIONS||{}).forEach(byAno=>Object.values(byAno||{}).forEach(byComp=>Object.values(byComp||{}).forEach(set=>scanSets.push(set))));
  for(const set of scanSets){
    if(!set||typeof set!=='object') continue;
    for(const [key,info] of Object.entries(set)){
      if(normalizeSkillKey(key)===h || normalizeSkillKey(info?.codigo)===h) return info;
    }
  }
  return null;
}
function adrSkillDisplay(codigo, ano, componente, adr, includeAdr=false) {
  const adrKey = adrNormAdrSkill(adr);
  const anoKey = adrNormAnoSkill(ano);
  const compKey = adrNormCompSkill(componente);
  const prefix = includeAdr && adrKey ? `${adrKey} · ` : '';
  const info = adrSkillInfo(codigo, ano, componente, adr);
  if(!info) {
    return {
      label: `${prefix}${codigo}`,
      desc: `Habilidade ${codigo} — matriz oficial não carregada para ${adrKey || 'esta ADR'} · ${anoKey || 'ano'} · ${compKey || 'componente'}.`,
      title: `${prefix}${codigo}`
    };
  }
  const cod = info.codigo ? ` · ${info.codigo}` : '';
  const extras = [info.faixa ? `Faixa rede: ${info.faixa}` : '', info.acerto ? `Acerto rede: ${info.acerto}%` : ''].filter(Boolean).join(' · ');
  const desc = extras ? `${info.descricao} | ${extras}` : info.descricao;
  return {label: `${prefix}${codigo}${cod}`, desc, title: `${prefix}${codigo}${cod}: ${info.descricao}`};
}


