function renderBanco() {
  const q=norm(document.getElementById('bankSearch').value), t=document.getElementById('filterTerritorio').value, ag=document.getElementById('filterAgente').value, pa=document.getElementById('filterPA').value, pd=document.getElementById('filterPD').value, ex=document.getElementById('filterExclusiva').value, pr=document.getElementById('filterPrioridade')?.value||'';
  let rows=DATA.records.filter(r=>(!window.graMasterAllowsRow||window.graMasterAllowsRow(r))&&(!t||String(r.territorio)===String(t))&&(!ag||r.agente===ag)&&(!pa||r.planoAcao===pa)&&(!pd||r.planoDimensao===pd)&&(!ex||r.exclusiva===ex)&&(!pr||(pr==='sim'?r.prioritaria==='Sim':r.prioritaria!=='Sim')));
  if(q) rows=rows.filter(r=>recordText(r).includes(q));
  if(pr==='sim'||q.includes('prioritaria')) rows=sortPriorityRows(rows);
  document.getElementById('bankCount').textContent = `${rows.length} de ${DATA.records.length} unidades exibidas.`;
  table('bankTable', rows, bankColumns);
}
