  renderBars('efpdPABars', DATA.efPdPlanoAcao.map(x=>({name:x.planoAcao, sub:x.observacao, value:x.total, note:pct(x.percentual)})), Math.max(...DATA.efPdPlanoAcao.map(x=>x.total)));
