const SOM_STORAGE_DB='GRA2CRE_Dashboard_Somativas';
const SOM_STORAGE_STORE='dados';
const SOM_STORAGE_KEY='somRowsV175_agentes_cre2_cre8_ppi';
function somOpenStorageDb(){ return new Promise((resolve,reject)=>{ if(!('indexedDB' in window)) return reject(new Error('Armazenamento local indisponível neste navegador.')); const req=indexedDB.open(SOM_STORAGE_DB,1); req.onupgradeneeded=()=>{ const db=req.result; if(!db.objectStoreNames.contains(SOM_STORAGE_STORE)) db.createObjectStore(SOM_STORAGE_STORE); }; req.onsuccess=()=>resolve(req.result); req.onerror=()=>reject(req.error||new Error('Não foi possível abrir o armazenamento local.')); }); }
async function somStorageSet(key,value){ const db=await somOpenStorageDb(); return new Promise((resolve,reject)=>{ const tx=db.transaction(SOM_STORAGE_STORE,'readwrite'); tx.objectStore(SOM_STORAGE_STORE).put(value,key); tx.oncomplete=()=>{db.close();resolve();}; tx.onerror=()=>{ const err=tx.error; db.close(); reject(err||new Error('Erro ao salvar.'));}; }); }
async function somStorageGet(key){ const db=await somOpenStorageDb(); return new Promise((resolve,reject)=>{ const tx=db.transaction(SOM_STORAGE_STORE,'readonly'); const req=tx.objectStore(SOM_STORAGE_STORE).get(key); req.onsuccess=()=>{db.close();resolve(req.result);}; req.onerror=()=>{ const err=req.error; db.close(); reject(err||new Error('Erro ao carregar.'));}; }); }
async function somStorageDelete(key){ const db=await somOpenStorageDb(); return new Promise((resolve,reject)=>{ const tx=db.transaction(SOM_STORAGE_STORE,'readwrite'); tx.objectStore(SOM_STORAGE_STORE).delete(key); tx.oncomplete=()=>{db.close();resolve();}; tx.onerror=()=>{ const err=tx.error; db.close(); reject(err||new Error('Erro ao limpar.'));}; }); }
async function somSaveStored(){ const status=document.getElementById('somUploadStatus'); try{ await somStorageSet(SOM_STORAGE_KEY,{savedAt:new Date().toISOString(), rows:SOM_ROWS}); if(status) status.innerHTML=`<b>Bases somativas salvas no navegador.</b> ${SOM_ROWS.length.toLocaleString('pt-BR')} registros ficarão disponíveis ao reabrir esta dashboard neste computador/navegador.`; }catch(e){ if(status) status.innerHTML=`<b>Não foi possível salvar.</b> ${esc(e.message||e)}.`; } }
async function somLoadStored(silent=false){ const status=document.getElementById('somUploadStatus'); try{ const saved=await somStorageGet(SOM_STORAGE_KEY); if(saved && Array.isArray(saved.rows) && saved.rows.length){ SOM_ROWS=saved.rows.map(somRepairProvaRioLevelRow); somRefreshSelectors(); renderSomFileChips(); renderResultados(); const when=saved.savedAt?new Date(saved.savedAt).toLocaleString('pt-BR'):'data não registrada'; if(status) status.innerHTML=`<b>Bases somativas salvas carregadas automaticamente.</b> ${SOM_ROWS.length.toLocaleString('pt-BR')} registros recuperados. Último salvamento: ${esc(when)}.`; return true; } }catch(e){ if(!silent && status) status.innerHTML=`<b>Não foi possível carregar as bases salvas.</b> ${esc(e.message||e)}.`; } return false; }
async function somClearStored(){ const status=document.getElementById('somUploadStatus'); try{ await somStorageDelete(SOM_STORAGE_KEY); SOM_ROWS=SOM_INITIAL.slice(); somRefreshSelectors(); renderSomFileChips(); renderResultados(); if(status) status.innerHTML='<b>Bases somativas removidas.</b> A aba ficou sem bases carregadas. Envie um arquivo para iniciar a análise.'; }catch(e){ if(status) status.innerHTML=`<b>Não foi possível limpar as bases.</b> ${esc(e.message||e)}.`; } }
function initResultados() {
  if(!document.getElementById('resultados')) return;
  SOM_INITIAL=somBuildInitialRows();
  SOM_ROWS=SOM_INITIAL.slice();
  somRefreshSelectors(); renderSomFileChips(); renderResultados();
  somLoadStored(true);
  const saveBtn=document.getElementById('somSaveBtn'); if(saveBtn) saveBtn.addEventListener('click',somSaveStored);
  const clearBtn=document.getElementById('somClearBtn'); if(clearBtn) clearBtn.addEventListener('click',somClearStored);
  ['somMode','somModalidade','somAnoEscolar','somComponente','somEdicao','somMetric','somCre','somAgente','somPriority','somSearch'].forEach(id=>{
    const el=document.getElementById(id); if(!el) return;
    el.addEventListener(id==='somSearch'?'input':'change',async()=>{ try{if(['somModalidade','somAnoEscolar','somComponente'].includes(id)&&document.getElementById('somModalidade')?.value==='Simulado 2026'){const host=document.getElementById('somMainChart');if(host)host.innerHTML='<div class="sim2026-loading">Carregando apenas o recorte selecionado do Simulado 2026…</div>';await sim2026EnsureForSom();} if(['somModalidade','somAnoEscolar','somComponente'].includes(id)) somRefreshSelectors(); if(id==='somModalidade') somAdjustMetricOptions(); renderResultados();}catch(err){console.error(err);const host=document.getElementById('somMainChart');if(host)host.innerHTML=`<div class="sim2026-loading">Não foi possível abrir este recorte do Simulado 2026.<br>${esc(err.message||err)}</div>`;} });
  });
  const fileInput=document.getElementById('somFileInput');
  if(fileInput) fileInput.addEventListener('change', async ev=>{
    const files=[...ev.target.files]; if(!files.length) return;
    const meta={ modalidade:document.getElementById('somUploadModalidade')?.value||'', anoEscolar:document.getElementById('somUploadAnoEscolar')?.value||'', componente:document.getElementById('somUploadComp')?.value||'', edicao:document.getElementById('somUploadEdicao')?.value||'' };
    const status=document.getElementById('somUploadStatus');
    if(status) status.innerHTML=`<b>Lendo arquivos...</b> Classificação aplicada: ${esc(meta.modalidade)} · ${esc(meta.anoEscolar)} · ${esc(meta.componente)} · ${esc(meta.edicao)}.`;
    let added=0, errors=[], addedRows=[];
    for(const file of files){
      try{
        const rows=await somReadFile(file,meta);
        SOM_ROWS.push(...rows); addedRows.push(...rows); added+=rows.length;
      } catch(e){ errors.push(`${file.name}: ${e.message}`); }
    }
    somRefreshSelectors();
    document.getElementById('somModalidade').value=meta.modalidade;
    document.getElementById('somAnoEscolar').value=meta.anoEscolar;
    document.getElementById('somComponente').value=meta.componente;
    const actualEds=somUnique(addedRows.map(r=>r.edicao));
    const edToSelect=(actualEds.length===1 ? actualEds[0] : meta.edicao);
    if(document.getElementById('somEdicao')) document.getElementById('somEdicao').value=edToSelect;
    if(document.getElementById('somCre')) document.getElementById('somCre').value='';
    if(document.getElementById('somAgente')) document.getElementById('somAgente').value='';
    renderSomFileChips(); renderResultados();
    if(status) status.innerHTML=`<b>${added.toLocaleString('pt-BR')} registros adicionados.</b> Classificados como ${esc(meta.modalidade)} · ${esc(meta.anoEscolar)} · ${esc(meta.componente)} · ${esc(actualEds.length===1?actualEds[0]:meta.edicao)}. Use “Salvar bases carregadas” para manter os dados ao reabrir a dashboard.${errors.length?' Erros: '+esc(errors.join(' | ')):''}`;
    ev.target.value='';
  });
}



