function v104AplicarCorrecaoCanonicaJoaoGoulart(obj){
  if(!obj||typeof obj!=='object')return;
  if(Array.isArray(obj)){obj.forEach(v104AplicarCorrecaoCanonicaJoaoGoulart);return;}
  const nome=String(obj.unidade||obj.name||obj.dataRioName||'').trim().toLowerCase();
  if(nome==='ciep presidente joão goulart'){
    if('planoAcao' in obj)obj.planoAcao='EF AI';
    if('segment' in obj)obj.segment='AI';
    if('segmento' in obj)obj.segmento='AI';
    if('idebAF' in obj)obj.idebAF='--';
    if('pesoEF' in obj)obj.pesoEF=1;
  }
  Object.keys(obj).forEach(k=>v104AplicarCorrecaoCanonicaJoaoGoulart(obj[k]));
}
