    const value=geoNum(r?.[field]);
    if(Number.isFinite(value)){
      const isPercent=['Avalia RJ','Prova Rio'].includes(String(r?.modalidade||''))||r?.resultadoTipo==='percentualNiveis'||['acerto','adequado','adqAv'].includes(field);
      return {field,value,suffix:isPercent?'%':''};
    }
