  const rows=(SOM_ROWS||[]).filter(x=>geoIsCre2Row(x)&&String(x.modalidade||'')===modality&&String(x.avaliacao||'')===evaluation&&String(x.edicao||'')===edition&&String(x.anoEscolar||'')===year&&String(x.componente||'')===component);
