function geoSomReference(r){
  const metric=geoSomMetric(r);
  if(!Number.isFinite(metric.value))return '<div class="geo-mini-metrics"><span class="geo-mini-value">—</span></div>';
  const median=geoSomMedian(r,metric.field);
  let badge='';
  if(Number.isFinite(median)){
    const diff=metric.value-median,cls=Math.abs(diff)<=.05?'equal':diff>0?'above':'below',label=Math.abs(diff)<=.05?'Na mediana':diff>0?'Acima da mediana':'Abaixo da mediana';
    badge=`<span class="geo-mini-reference ${cls}">${label}</span>`;
  }
  return `<div class="geo-mini-metrics"><span class="geo-mini-value">${geoFmt(metric.value,1)}${metric.suffix}</span>${Number.isFinite(median)?`<span class="geo-mini-median">Mediana do recorte: ${geoFmt(median,1)}${metric.suffix}</span>${badge}`:''}</div>`;
}
function geoSomValue(r) { const metric=geoSomMetric(r); return Number.isFinite(metric.value)?`${geoFmt(metric.value,1)}${metric.suffix}`:'—'; }
function geoAdrOverview(point){
  if(!GEO_STATE.adrReady)return '<div class="geo-adr-loading">Preparando a comparação das ADRs…</div>';
  const rows=[]; for(const year of ['2º ano','4º ano','5º ano','8º ano','9º ano'])for(const comp of ['LP','MT']){const r1=geoFinishAggregate(GEO_STATE.adrIndex.get(geoAdrIndexKey(point.name,year,comp,'ADR 1'))),r2=geoFinishAggregate(GEO_STATE.adrIndex.get(geoAdrIndexKey(point.name,year,comp,'ADR 2')));if(r1&&r2)rows.push({year,comp,r1,r2});}
  if(!rows.length)return '<div class="geo-empty">Não há comparação completa entre ADR 1 e ADR 2 para esta unidade.</div>';
  return `<div class="geo-adr-overview">${rows.map(x=>`<div class="geo-adr-overview-row"><strong>${esc(x.year)} · ${esc(x.comp)}</strong><div class="geo-adr-metrics"><div class="geo-adr-metric"><small>Adequado</small><span>${geoFmt(x.r1.adequado,1)}% → ${geoFmt(x.r2.adequado,1)}%</span>${geoDeltaBadge(x.r2.adequado-x.r1.adequado)}</div><div class="geo-adr-metric"><small>Abaixo do Básico</small><span>${geoFmt(x.r1.abaixo,1)}% → ${geoFmt(x.r2.abaixo,1)}%</span>${geoDeltaBadge(x.r1.abaixo-x.r2.abaixo)}</div></div></div>`).join('')}</div>`;
}
function geoOpenDetail(point){
  GEO_STATE.selected=point.name;geoRenderMarkers();const detail=document.getElementById('geoDetail');if(!detail)return;
  const photo=GEO_AGENT_PHOTOS[point.agent]||'',pos=GEO_AGENT_PHOTO_POS[point.agent]||'50% 25%';const somRows=(SOM_ROWS||[]).filter(r=>geoIsCre2Row(r)&&somFindRecord(r.escola||'')?.unidade===point.name);const ideb=somRows.filter(r=>String(r.modalidade||'').includes('IDEB'));const pick=segment=>ideb.filter(r=>r.anoEscolar===segment).sort((a,b)=>Number(b.edicao||0)-Number(a.edicao||0))[0]||null;const nonIdeb=somRows.filter(r=>!String(r.modalidade||'').includes('IDEB')&&r.modalidade!=='Simulado 2026').sort((a,b)=>Number(b.edicao||0)-Number(a.edicao||0));const uniq=[],seen=new Set();nonIdeb.forEach(r=>{const k=[r.modalidade,r.edicao,r.anoEscolar,r.componente].join('|');if(!seen.has(k)){seen.add(k);uniq.push(r);}});
  detail.innerHTML=`<div class="geo-detail-head"><div><h3>${esc(point.name)}</h3><div class="geo-detail-tags"><span class="chip">${esc(point.segment)}</span>${priorityMetaForSchool(point.name)?'<span class="priority-badge">Prioritária</span>':''}<span class="chip">T${esc(point.territory)}</span></div></div><button class="geo-detail-close" data-gra-no-school-nav="1" type="button" aria-label="Fechar">×</button></div><div class="geo-detail-body"><div class="geo-agent">${photo?`<img class="geo-agent-photo" src="${photo}" alt="Foto de ${esc(point.agent)}" style="object-position:${pos}">`:'<div class="geo-agent-photo"></div>'}<div><small>Agente GRA</small><strong>${esc(point.agent)}</strong></div></div><div class="geo-result-block"><div class="geo-result-title"><strong>IDEB — análise integrada</strong><span>2023 → 2025</span></div><div class="geo-ideb-grid">${geoIdebCard('Anos Iniciais',pick('Anos Iniciais'),point.idebAI)}${geoIdebCard('Anos Finais',pick('Anos Finais'),point.idebAF)}</div></div><div class="geo-result-block"><div class="geo-result-title"><strong>Demais avaliações somativas</strong><span>resultados mais recentes</span></div>${uniq.length?`<div class="geo-mini-list">${uniq.slice(0,8).map(r=>`<div class="geo-mini-row"><div><strong>${esc(r.modalidade||r.avaliacao||'Avaliação')}</strong><span>${esc([r.anoEscolar,r.componente,r.edicao].filter(Boolean).join(' · '))}</span></div>${geoSomReference(r)}</div>`).join('')}</div>`:'<div class="geo-empty">Não há outra avaliação somativa pré-carregada para esta unidade.</div>'}</div><div class="geo-result-block"><div class="geo-result-title"><strong>ADRs — visão consolidada</strong><span>ADR 1 → ADR 2</span></div>${geoAdrOverview(point)}</div></div>`;
  detail.querySelector('.geo-detail-close').onclick=(event)=>{event?.preventDefault?.();event?.stopPropagation?.();geoCloseDetail();};detail.classList.add('open');detail.setAttribute('aria-hidden','false');geoUpdateLegend();
  if(!GEO_STATE.adrReady)geoBuildAdrIndex(()=>{if(GEO_STATE.selected===point.name)geoOpenDetail(point);});
}


/* v296 — visualização 3D removida por desempenho. Stubs mantêm compatibilidade com patches históricos. */
const GEO_3D_STATE={mode:'2d',map:null,popup:null};
function geo3dUpdatePoints(){}
function geo3dFitToPoints(){}
function geo3dScheduleRebuild(){}
function geoSetViewMode(){return '2d';}

function ensureGeoMap(){
  geoInitStage();
  return GEO_STATE;
}
function geoScheduleFilters(delay=80){
  clearTimeout(GEO_STATE.filterTimer);
  GEO_STATE.pendingFilterRender=true;
  GEO_STATE.filterTimer=setTimeout(()=>{
    GEO_STATE.evalCache.clear();
    GEO_STATE.evolutionCache.clear();
    geoUpdateContextUI();
    const active=document.getElementById('georreferenciamento')?.classList.contains('active');
    if(!active){GEO_STATE.pendingFilterRender=true;return;}
    const pts=geoVisiblePoints();
    if(pts.length){
      geoFitToPoints(pts);
    }else{
      geoRender();
    }
    GEO_STATE.pendingFilterRender=false;
    GEO_STATE.needsInitialFit=false;
  },delay);
}
function populateGeoAgentFilter(){
  const sel=document.getElementById('geoAgent');if(!sel||sel.dataset.ready==='1')return;
  const agents=[...new Set((GEO_POINTS||[]).map(p=>String(p.agent||'').trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'pt-BR',{sensitivity:'base'}));
  sel.innerHTML=`<option value="${GEO_ALL_SCHOOLS_VALUE}">Todas as escolas</option><option value="">Todos os agentes</option>`+agents.map(a=>`<option value="${esc(a)}">${esc(a)}</option>`).join('');sel.value=GEO_ALL_SCHOOLS_VALUE;sel.dataset.ready='1';
}
function geoSetOptions(select,items,preferred=''){
  if(!select)return;
  const current=preferred||select.value;
  select.innerHTML=items.map(x=>`<option value="${esc(x.value)}">${esc(x.label)}</option>`).join('');
  if(items.some(x=>x.value===current))select.value=current;else if(items.length)select.value=items[0].value;
}
function geoRowsForEvaluationFilters(evaluation,segment='',component=''){
  if(evaluation==='ADR')return [];
  return (Array.isArray(SOM_ROWS)?SOM_ROWS:[]).filter(r=>{
    if(r.modalidade!==evaluation)return false;
    if(typeof geoIsCre2Row==='function'&&!geoIsCre2Row(r))return false;
    if(segment&&!geoRowMatchesYearFilter(r.anoEscolar,segment))return false;
    if(component&&typeof somComponentMatches==='function'&&!somComponentMatches(r.componente,component,r.modalidade))return false;
    return true;
  });
}
function geoMetricAvailable(rows,key){return rows.some(r=>Number.isFinite(Number(key==='principal'?geoSomMetricValue(r,{indicator:'principal',component:document.getElementById('geoEvalComponent')?.value||''}):r[key])));}
function geoRefreshEvaluationFilters(keep=true){
  const evaluation=GEO_STATE.evaluation||'ADR';
  const filters=document.getElementById('geoEvalFilters');
  const seg=document.getElementById('geoEvalSegment'),adrView=document.getElementById('geoAdrView'),comp=document.getElementById('geoEvalComponent'),ind=document.getElementById('geoEvalIndicator');
  const segmentWrap=document.getElementById('geoEvalSegmentWrap'),adrViewWrap=document.getElementById('geoAdrViewWrap'),componentWrap=document.getElementById('geoEvalComponentWrap');
  const segmentLabelEl=segmentWrap?.querySelector('span');
  const indicatorLabelEl=document.getElementById('geoEvalIndicatorWrap')?.querySelector('span');
  const exactYearMode=(evaluation==='ADR'||evaluation==='Prova Rio'||evaluation==='Simulado Prova Rio'||evaluation==='Simulado 2026');
  const isIdeb=evaluation==='IDEB 2025';
  const isAdr=evaluation==='ADR';
  filters?.classList.toggle('is-adr',isAdr);
  if(segmentLabelEl)segmentLabelEl.textContent=exactYearMode?'Ano':'Segmento';
  if(indicatorLabelEl)indicatorLabelEl.textContent=isIdeb?'Visualização':'Indicador';
  if(adrViewWrap)adrViewWrap.hidden=!isAdr;
  const saved=GEO_STATE.evalSelections[evaluation]||{};
  if(isAdr){
    geoSetOptions(adrView,[
      {value:'adr1',label:'ADR 1'},
      {value:'adr2',label:'ADR 2'},
      {value:'progress',label:'Progresso'}
    ],keep?(saved.adrView||adrView?.value||'progress'):'progress');
  }
  if(evaluation==='Avalia RJ'){
    segmentWrap.hidden=true;componentWrap.hidden=true;
  }else{
    segmentWrap.hidden=false;componentWrap.hidden=isIdeb;
    const rows=geoRowsForEvaluationFilters(evaluation);
    const items=[];
    if(isAdr){
      items.push({value:'2º ano',label:'2º ano'},{value:'4º ano',label:'4º ano'},{value:'5º ano',label:'5º ano'},{value:'8º ano',label:'8º ano'},{value:'9º ano',label:'9º ano'});
    }else if(evaluation==='Simulado 2026'){
      items.push({value:'2º ano',label:'2º ano'},{value:'4º ano',label:'4º ano'},{value:'8º ano',label:'8º ano'});
    }else if(exactYearMode){
      [...new Set(rows.map(r=>String(r.anoEscolar||'').trim()).filter(Boolean))]
        .sort((a,b)=>geoYearSortValue(a)-geoYearSortValue(b)||String(a).localeCompare(String(b),'pt-BR',{sensitivity:'base'}))
        .forEach(year=>items.push({value:year,label:year}));
    }else{
      const segments=[...new Set(rows.map(r=>geoYearSegment(r.anoEscolar)).filter(Boolean))];
      if(segments.includes('AI'))items.push({value:'AI',label:'Anos Iniciais'});
      if(segments.includes('AF'))items.push({value:'AF',label:'Anos Finais'});
    }
    geoSetOptions(seg,items.length?items:[{value:exactYearMode?'1º ano':'AI',label:exactYearMode?'1º ano':'Anos Iniciais'}],keep?(saved.segment||seg.value):'');
  }
  const segment=evaluation==='Avalia RJ'?'':(seg?.value||'');
  const currentAdrView=isAdr?(adrView?.value||'progress'):'';
  let componentItems=[];
  if(isAdr)componentItems=[{value:'LP',label:'Língua Portuguesa'},{value:'MT',label:'Matemática'}];
  else if(evaluation==='Avalia RJ')componentItems=[{value:'',label:'LP + MT combinados'}];
  else if(isIdeb)componentItems=[{value:'',label:'IDEB'}];
  else if(evaluation==='Simulado 2026')componentItems=segment==='2º ano'
    ?[{value:'LP',label:'Língua Portuguesa'}]
    :[{value:'LP',label:'Língua Portuguesa'},{value:'MT',label:'Matemática'}];
  else{
    const rows=geoRowsForEvaluationFilters(evaluation,segment);
    const comps=[...new Set(rows.flatMap(r=>{
      const c=String(r.componente||'');if(c==='LP+MT')return ['LP','MT'];return ['LP','MT'].includes(c)?[c]:[];
    }))];
    if(comps.includes('LP'))componentItems.push({value:'LP',label:'Língua Portuguesa'});
    if(comps.includes('MT'))componentItems.push({value:'MT',label:'Matemática'});
  }
  geoSetOptions(comp,componentItems.length?componentItems:[{value:'',label:'Resultado'}],keep?(saved.component||comp.value):'');
  const sim2LiteracyLocked=evaluation==='Simulado 2026'&&segment==='2º ano';
  if(comp){
    if(sim2LiteracyLocked)comp.value='LP';
    comp.disabled=sim2LiteracyLocked;
    comp.setAttribute('aria-disabled',String(sim2LiteracyLocked));
    comp.title=sim2LiteracyLocked?'No 2º ano, o Georreferenciamento usa alfabetização em Língua Portuguesa.':'';
  }
  const component=comp?.value||'';
  let indicatorItems=[];
  if(isAdr&&currentAdrView==='progress')indicatorItems=[
    {value:'adequado',label:'% Adequado'},{value:'abaixo',label:'% Abaixo do Básico'},{value:'avaliadosPct',label:'% Avaliados'}
  ];
  else if(isAdr)indicatorItems=[
    {value:'adequado',label:'% Adequado'},{value:'abaixo',label:'% Abaixo do Básico'},{value:'avaliadosPct',label:'% Avaliados'}
  ];
  else if(evaluation==='Avalia RJ')indicatorItems=[{value:'alfabetizacaoCombinada',label:'% de alfabetização combinada (LP + MT)'}];
  else if(isIdeb)indicatorItems=[
    {value:'ideb2023',label:'IDEB 2023'},
    {value:'ideb2025',label:'IDEB 2025'},
    {value:'crescimento',label:'Progressão 2023 → 2025'}
  ];
  else if(evaluation==='Simulado 2026') indicatorItems=segment==='2º ano'
    ?[{value:'alfabetizacaoMeta',label:'% Alfabetizados'}]
    :[{value:'notaPadronizada',label:'Nota Padronizada'}];
  else{
    const rows=geoRowsForEvaluationFilters(evaluation,segment,component);
    const ordered=evaluation==='Prova Rio'
      ? [['adqAv','% Adequado + Avançado'],['adequado','% Adequado'],['avancado','% Avançado'],['basico','% Básico'],['abaixo','% Abaixo do Básico']]
      : [['principal','Resultado principal'],['adqAv','% Adequado + Avançado'],['adequado','% Adequado'],['avancado','% Avançado'],['basico','% Básico'],['abaixo','% Abaixo do Básico'],['acerto','% Acerto Total']];
    indicatorItems=ordered.filter(([key])=>geoMetricAvailable(rows,key)).map(([value,label])=>({value,label}));
  }
  let preferredIndicator=keep?(saved.indicator||ind.value):'';
  if(evaluation==='Prova Rio'&&(preferredIndicator==='principal'||!indicatorItems.some(item=>item.value===preferredIndicator)))preferredIndicator='adqAv';
  const indicatorFallback=evaluation==='Prova Rio'?{value:'adqAv',label:'% Adequado + Avançado'}:{value:'principal',label:'Resultado principal'};
  geoSetOptions(ind,indicatorItems.length?indicatorItems:[indicatorFallback],preferredIndicator);
  if(ind){
    const sim2Locked=evaluation==='Simulado 2026'&&segment==='2º ano';
    const simStdLocked=evaluation==='Simulado 2026'&&(segment==='4º ano'||segment==='8º ano');
    if(sim2Locked&&ind.value!=='alfabetizacaoMeta')ind.value='alfabetizacaoMeta';
    if(simStdLocked&&ind.value!=='notaPadronizada')ind.value='notaPadronizada';
    const locked=sim2Locked||simStdLocked;
    ind.disabled=locked;
    ind.setAttribute('aria-disabled',String(locked));
    ind.title=sim2Locked
      ?'No 2º ano em Língua Portuguesa, o resultado exibido no mapa é o % de alunos alfabetizados (proficiência ≥ 743). A cor continua comparando esse resultado com a meta da própria CRE.'
      :simStdLocked?'No 4º e no 8º ano, o indicador do mapa é a Nota Padronizada da escola.':'';
  }
  GEO_STATE.evalSelections[evaluation]={segment:segment,adrView:currentAdrView,component:comp?.value||'',indicator:ind?.value||''};
  GEO_STATE.evalCache.clear();GEO_STATE.evolutionCache.clear();geoUpdateContextUI();
}
function geoUpdateContextUI(){
  const ctx=geoEvalContext();const chip=document.getElementById('geoEvalContextChip'),note=document.getElementById('geoFilterNote');
  const segmentLabel=ctx.evaluation==='Avalia RJ'?'2º ano':geoYearFilterLabel(ctx.segment,'Todos os segmentos');
  const componentLabel=ctx.component==='LP'?'Língua Portuguesa':ctx.component==='MT'?'Matemática':'';
  const idebViewLabel=ctx.indicator==='ideb2023'?'IDEB 2023':ctx.indicator==='ideb2025'?'IDEB 2025':ctx.indicator==='crescimento'?'Progressão 2023 → 2025':'';
  if(chip){
    const priorityLabel=document.getElementById('geoPriority')?.value==='sim'?'Prioritárias':'';
    if(ctx.evaluation==='ADR')chip.textContent=[segmentLabel,componentLabel,ctx.edition,priorityLabel].filter(Boolean).join(' · ');
    else if(ctx.evaluation==='Avalia RJ')chip.textContent=`2º ano · alfabetização combinada LP + MT${ctx.edition?' · edição '+ctx.edition:''}${priorityLabel?' · '+priorityLabel:''}`;
    else if(ctx.evaluation==='IDEB 2025')chip.textContent=[segmentLabel,idebViewLabel,priorityLabel].filter(Boolean).join(' · ');
    else if(ctx.evaluation==='Simulado 2026'&&ctx.segment==='2º ano')
      chip.textContent=[segmentLabel,'Língua Portuguesa','% Alfabetizados',ctx.edition?`edição ${ctx.edition}`:'',priorityLabel].filter(Boolean).join(' · ');
    else chip.textContent=[segmentLabel,componentLabel,ctx.edition?`edição ${ctx.edition}`:'',priorityLabel].filter(Boolean).join(' · ');
  }
  if(note){
    if(ctx.evaluation==='ADR'){
      if(ctx.adrView==='progress')note.textContent='As cores mostram o progresso da ADR 1 para a ADR 2: Avançou, Estagnou ou Caiu. Clique em uma categoria da legenda para exibir somente seus balões.';
      else{
        const snap=geoAdrSnapshot(ctx);
        const polarityNote=ctx.indicator==='abaixo'?' No indicador Abaixo do Básico, valores menores são melhores: abaixo da mediana aparece em azul e acima da mediana em vermelho.':'';
        note.textContent=`As cores comparam cada escola à mediana da 2ª CRE na ${ctx.edition}. A faixa “Próximos da mediana” considera resultados a até 0,5 ponto percentual da mediana${Number.isFinite(snap.median)?' ('+geoFmt(snap.median,1)+'%)':''}.${polarityNote}`;
      }
    }else if(ctx.evaluation==='Avalia RJ'){
      const snap=geoSomSnapshot(ctx);
      note.textContent=`As cores comparam o resultado combinado de alfabetização em LP e MT de cada escola à mediana da 2ª CRE${Number.isFinite(snap.median)?' ('+geoFmt(snap.median,1)+'%)':''}. A faixa “Próximo da mediana” considera resultados a até 0,5 ponto percentual da mediana.`;
    }else if(ctx.evaluation==='IDEB 2025'){
      const snap=geoSomSnapshot(ctx);
      if(ctx.indicator==='crescimento')note.textContent='As cores mostram a progressão do IDEB de 2023 para 2025. Aparecem somente unidades com os dois resultados disponíveis.';
      else note.textContent=`As cores comparam o resultado de cada escola à mediana da 2ª CRE, calculada somente entre as ${snap.count} unidades com IDEB disponível no segmento selecionado.`;
    }else if(ctx.evaluation==='Simulado 2026'){
      if(ctx.segment==='2º ano'&&ctx.component==='LP'&&ctx.indicator==='alfabetizacaoMeta'){
        const scope=Number(document.getElementById('regionalScopeSelect')?.value||0);
        const target=scope?geo2AnoCreTarget(scope,'LP'):null;
        note.textContent=Number.isFinite(target)
          ?`No 2º ano em Língua Portuguesa, o resultado exibido é o % de alunos alfabetizados (proficiência ≥ 743). Cada escola é comparada à meta de alfabetização da ${scope}ª CRE (${geoFmt(target,0)}%). Azul indica meta atingida ou superada; vermelho indica abaixo da meta.`
          :'No 2º ano em Língua Portuguesa, o resultado exibido é o % de alunos alfabetizados (proficiência ≥ 743). Cada escola é comparada à meta de alfabetização da sua própria CRE. Azul indica meta atingida ou superada; vermelho indica abaixo da meta.';
      }else note.textContent=`As cores comparam cada escola à mediana do universo regional selecionado no Simulado 2026. Os filtros de ano, componente, indicador e agente atuam diretamente sobre o mapa.`;
    }
    else note.textContent=`As cores comparam o resultado de cada escola à mediana do universo selecionado${ctx.edition?' (edição '+ctx.edition+')':''}.`;
    if(document.getElementById('geoPriority')?.value==='sim')note.textContent+=' Filtro ativo: somente unidades prioritárias compatíveis com o ano ou segmento selecionado.';
  }
  geoUpdateLegend();
}
async function geoSelectEvaluation(evaluation){
  const current=GEO_STATE.evaluation;const seg=document.getElementById('geoEvalSegment'),adrView=document.getElementById('geoAdrView'),comp=document.getElementById('geoEvalComponent'),ind=document.getElementById('geoEvalIndicator');
  if(current)GEO_STATE.evalSelections[current]={segment:seg?.value||'',adrView:current==='ADR'?(adrView?.value||'progress'):'',component:comp?.value||'',indicator:ind?.value||''};
  GEO_STATE.evaluation=evaluation;GEO_STATE.legendStatus='';GEO_STATE.evalCache.clear();GEO_STATE.evolutionCache.clear();
  document.querySelectorAll('[data-geo-eval]').forEach(btn=>{const active=btn.dataset.geoEval===evaluation;btn.classList.toggle('active',active);btn.setAttribute('aria-selected',String(active));});
  if(evaluation==='Simulado 2026'){
    geoRefreshEvaluationFilters(true);
    try{await sim2026EnsureForGeo();}catch(err){console.error(err);}
    geoRefreshEvaluationFilters(true);geoScheduleFilters(0);return;
  }
  geoRefreshEvaluationFilters(true);geoScheduleFilters(0);
}
function initGeoref(){
  if(GEO_STATE.controlsBound)return;
  GEO_STATE.controlsBound=true;
  populateGeoAgentFilter();geoBindLegendEvents();
  document.querySelectorAll('[data-geo-eval]').forEach(btn=>btn.addEventListener('click',()=>geoSelectEvaluation(btn.dataset.geoEval)));
  document.getElementById('geoEvalSegment')?.addEventListener('change',async()=>{const e=GEO_STATE.evaluation;GEO_STATE.evalSelections[e]={...(GEO_STATE.evalSelections[e]||{}),segment:document.getElementById('geoEvalSegment').value};GEO_STATE.legendStatus='';if(e==='Simulado 2026'){const y=document.getElementById('geoEvalSegment').value,c=y==='2º ano'?'LP':(['LP','MT'].includes(document.getElementById('geoEvalComponent')?.value)?document.getElementById('geoEvalComponent').value:'LP');try{await sim2026EnsureYearForIndicator(y,c);}catch(err){console.error(err);}}geoRefreshEvaluationFilters(true);geoScheduleFilters(20);});
  document.getElementById('geoAdrView')?.addEventListener('change',()=>{const e=GEO_STATE.evaluation;GEO_STATE.evalSelections[e]={...(GEO_STATE.evalSelections[e]||{}),adrView:document.getElementById('geoAdrView').value,indicator:''};GEO_STATE.legendStatus='';geoRefreshEvaluationFilters(true);geoScheduleFilters(20);});
  document.getElementById('geoEvalComponent')?.addEventListener('change',async()=>{const e=GEO_STATE.evaluation;GEO_STATE.evalSelections[e]={...(GEO_STATE.evalSelections[e]||{}),component:document.getElementById('geoEvalComponent').value};GEO_STATE.legendStatus='';if(e==='Simulado 2026'){const y=['2º ano','4º ano','8º ano'].includes(document.getElementById('geoEvalSegment')?.value)?document.getElementById('geoEvalSegment').value:'2º ano',c=y==='2º ano'?'LP':(document.getElementById('geoEvalComponent').value||'LP');try{await sim2026EnsureYearForIndicator(y,c);}catch(err){console.error(err);}}geoRefreshEvaluationFilters(true);geoScheduleFilters(20);});
  document.getElementById('geoEvalIndicator')?.addEventListener('change',()=>{const e=GEO_STATE.evaluation;GEO_STATE.evalSelections[e]={...(GEO_STATE.evalSelections[e]||{}),indicator:document.getElementById('geoEvalIndicator').value};GEO_STATE.legendStatus='';geoScheduleFilters(20);});
  ['geoPriority','geoGet','geoAgent'].forEach(id=>document.getElementById(id)?.addEventListener('change',()=>geoScheduleFilters(20)));
  document.getElementById('regionalScopeSelect')?.addEventListener('change',()=>{GEO_STATE.somIndexSize=-1;GEO_STATE.somIndexScope=null;GEO_STATE.evalCache.clear();GEO_STATE.evolutionCache.clear();GEO_STATE.legendStatus='';geoRefreshEvaluationFilters(true);geoScheduleFilters(20);});
  document.getElementById('geoSearch')?.addEventListener('input',event=>{
    if(GEO_STATE.focusedSchool&&norm(event.target.value)!==norm(GEO_STATE.focusedSchool)){
      const focused=GEO_STATE.focusedSchool;
      GEO_STATE.focusedSchool='';
      const global=document.getElementById('globalSearch');
      if(global&&norm(global.value)===norm(focused))global.value='';
    }
    geoScheduleFilters(140);
  });
  GEO_STATE.evaluation='ADR';document.querySelectorAll('[data-geo-eval]').forEach(btn=>{const active=btn.dataset.geoEval==='ADR';btn.classList.toggle('active',active);btn.setAttribute('aria-selected',String(active));});geoRefreshEvaluationFilters(true);if(!GEO_STATE.adrReady)setTimeout(()=>geoBuildAdrIndex(),250);
}

// v66 — filtros AI/AF incluem unidades mistas e ocultam escolas sem dados em seleções de ADR
// v64 — filtro por agente no mapa georreferenciado
function initNav() {
  const openSection=(btn)=>{
    const id=btn.dataset.section; if(!id) return;
    document.querySelectorAll('.nav button[data-section]').forEach(b=>b.classList.remove('active')); btn.classList.add('active');
    document.querySelectorAll('.section').forEach(s=>s.classList.remove('active'));
    const section=document.getElementById(id); if(section) section.classList.add('active');
    const group=btn.closest('.nav-group'); if(group) group.classList.add('open');
    if(id==='georreferenciamento')setTimeout(()=>{try{window.__graActivateSection?.('georreferenciamento');}catch(error){console.warn('Abertura do georreferenciamento',error);}},20);if(id==='banco')setTimeout(()=>sim2026BankEnsureAndRender(),30);
    window.scrollTo({top:0,behavior:'smooth'});
  };
  document.querySelectorAll('.nav button[data-section]').forEach(btn=>btn.onclick=()=>openSection(btn));
  document.querySelectorAll('.nav-parent[data-group-toggle]').forEach(parent=>parent.onclick=()=>{
    const group=parent.closest('.nav-group'); if(!group) return;
    const wasOpen=group.classList.contains('open'); group.classList.toggle('open',!wasOpen);
    if(!wasOpen && !group.querySelector('.nav-submenu .active')) { const first=group.querySelector('.nav-submenu button[data-section]'); if(first) openSection(first); }
  });
}

initNav(); initGlobalSearch(); initResultados();
